#include "mainwindow.hpp"

#include "ui_mainwindow.h" // generated by uic from mainwindow.ui

#include <QFile>
#include <QIcon>
#include <QListWidgetItem>
#include <QMessageBox>

#include <algorithm>

MainWindow::MainWindow(TaskList& tasks, QWidget* parent)
    : QMainWindow(parent)
    , ui_(std::make_unique<Ui::MainWindow>())
    , tasks_(tasks)
{
    ui_->setupUi(this);
    setWindowIcon(QIcon(":/icons/app.svg"));

    connect(ui_->addButton, &QPushButton::clicked, this, &MainWindow::addFromInput);
    connect(ui_->newTask, &QLineEdit::returnPressed, this, &MainWindow::addFromInput);
    connect(ui_->removeButton, &QPushButton::clicked, this, &MainWindow::removeSelected);
    connect(ui_->clearDoneButton, &QPushButton::clicked, &tasks_, &TaskList::clearDone);
    connect(ui_->actionAbout, &QAction::triggered, this, &MainWindow::showAbout);
    connect(ui_->list, &QListWidget::itemChanged, this, [this](QListWidgetItem* item) {
        if (!refreshing_) {
            tasks_.setDone(ui_->list->row(item), item->checkState() == Qt::Checked);
        }
    });
    connect(&tasks_, &TaskList::changed, this, &MainWindow::refresh);
    refresh();
}

MainWindow::~MainWindow() = default;

QString MainWindow::aboutText()
{
    QFile file(":/about.txt");
    if (!file.open(QIODevice::ReadOnly | QIODevice::Text)) {
        return {};
    }
    return QString::fromUtf8(file.readAll()).trimmed();
}

void MainWindow::addFromInput()
{
    tasks_.add(ui_->newTask->text());
    ui_->newTask->clear();
    ui_->newTask->setFocus();
}

void MainWindow::removeSelected()
{
    tasks_.remove(ui_->list->currentRow());
}

void MainWindow::refresh()
{
    refreshing_ = true;
    const int selected = ui_->list->currentRow();
    ui_->list->clear();
    for (int i = 0; i < tasks_.count(); ++i) {
        const Task& task = tasks_.at(i);
        auto* item = new QListWidgetItem(task.title, ui_->list);
        item->setFlags(item->flags() | Qt::ItemIsUserCheckable);
        item->setCheckState(task.done ? Qt::Checked : Qt::Unchecked);
        QFont font = item->font();
        font.setStrikeOut(task.done);
        item->setFont(font);
    }
    ui_->list->setCurrentRow(std::min(selected, tasks_.count() - 1));
    ui_->countLabel->setText(tr("%1 of %2 left").arg(tasks_.remaining()).arg(tasks_.count()));
    refreshing_ = false;
}

void MainWindow::showAbout()
{
    QMessageBox::about(this, tr("About Tasks"), aboutText());
}
